---@class ActivityMysteryItemCell
---@field Env                           	ActivityMysteryItemCell                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field GoodNode                      	UnityEngine.RectTransform               	@ 0    
---@field NumRoot                       	UnityEngine.RectTransform               	@ 1    
---@field TxtNum                        	UnityEngine.RectTransform               	@ 2    
local ActivityMysteryItemCell = Class("ActivityMysteryItemCell")

function ActivityMysteryItemCell:__init()

end

function ActivityMysteryItemCell:__delete()
    self.controller = nil
end

function ActivityMysteryItemCell:Awake()

end

function ActivityMysteryItemCell:RefreshShow(data)
    self.data = data
    self:RefreshStock()
    self:RefreshReward()
end

function ActivityMysteryItemCell:RefreshReward()
    ---@type GoodNodeMB
    local goodNodeMB = CfUtils.GetLuaScr(self.GoodNode,Constants.UILuaTablePath.GoodNodeMB)
    goodNodeMB:Reload({
        goodsId = self.data.rewardId,
        text = string.format("x%d", self.data.rewardNum),
        isShowNo = true
    })
    
    goodNodeMB:SetClickCallback(function()
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.rewardId)
        if isTable(vo) then
            GameUtils.ShowCommonTipsBoard(self.GoodNode, vo.name, vo.desc, vo.quality, vo.id)
        end
    end)
end

function ActivityMysteryItemCell:RefreshStock()
    local stock = self.data.currentStock
    if stock ~= -1 then
        CfUtils.FillText(self.TxtNum, localize("剩余：_num_",{_num_ = stock}))
        local canvasGroup =  CfUtils.GetOrAddComponent(self.NumRoot, CS.UnityEngine.CanvasGroup)
        canvasGroup.enabled = stock == 0
    else
        CfUtils.FillText(self.TxtNum,localize("无限库存"))
    end
    
    ---@type GoodNodeMB
    local goodNodeMB = CfUtils.GetLuaScr(self.GoodNode,Constants.UILuaTablePath.GoodNodeMB)
    if goodNodeMB then
        local isHaveStock = self:IsHaveStock()
        goodNodeMB:SetEnoughState(not isHaveStock)
    end
    
end

function ActivityMysteryItemCell:IsHaveStock()
    if self.data.currentStock == 0 then
        return false
    end
    
    return true
end

function ActivityMysteryItemCell:OnDestroy()
    self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
    self:Delete()
end

return ActivityMysteryItemCell